from pathlib import Path
import base64, hashlib, zlib

BASE_MAPLE = "3eb783852cb6fdb95571b377acecb3506b2bfd0cf43b6fe744984665724131b9"
BASE_UI = "616408f32e0be865f22ec70386d0fc13e53504c5a10634ab8b4f7b6cbc08fc3a"
OUT_MAPLE = "5f7a97629175640006f026886ffd3eed6f703aa2cb74113431c20a28ae866af9"
OUT_UI = "b22ae1169d2746edd00e328d4f3304edb2ac37de7d7f4b80eb4753ba9a4d723f"

HELPER_Z = ""
METHOD_Z = ""

def dec(s):
    return zlib.decompress(base64.b64decode(s)).decode("utf-8")

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

root = Path("portable/app_payload")
maple = root / "maple_nghia_pro.py"
ui = root / "nghia_spotify_nologin.py"
assert sha(maple) == BASE_MAPLE, sha(maple)
assert sha(ui) == BASE_UI, sha(ui)

text = maple.read_text(encoding="utf-8")
assert "def build_pirate_map_profile(" not in text
text = text.replace("def save_map_profile(target_path, maps_data, name, profile):\n", dec(HELPER_Z) + "def save_map_profile(target_path, maps_data, name, profile):\n", 1)
start = text.index("    def show_coordinate_map_builder(self):\n")
end = text.index("    def show_position_popup(self):\n", start)
text = text[:start] + dec(METHOD_Z) + text[end:]
maple.write_text(text, encoding="utf-8")

u = ui.read_text(encoding="utf-8")
assert "9.9.7" in u
u = u.replace("9.9.7", "9.9.8")
ui.write_text(u, encoding="utf-8")

assert sha(maple) == OUT_MAPLE, sha(maple)
assert sha(ui) == OUT_UI, sha(ui)
print("V998_SOURCE_TRANSFORM_OK")
